delete from university_links where university_id = (select id from universities where slug = 'ttu');
select (select id from universities where slug = 'ttu'), 'university', 'جامعة الطفيلة التقنية', 'مجتمع كل طلاب الجامعة' where not exists (select 1 from communities where university_id = (select id from universities where slug = 'ttu') and kind = 'university');
values ('wise', 'جامعة العلوم الإسلامية العالمية', 'The World Islamic Sciences and Education University', 'عمّان', 'public', array['wise.edu.jo']::text[], null, null, 'draft', 'College list is verbatim from the official homepage/menu (12 colleges incl. graduate college, which is omitted here). Programmes for Da''wah, Arts & Sciences, Educational Sciences, Finance & Business, Shafi''i and the Technical College (IT dept) come from the colleges'' ''البرامج المطروحة'' pages (degree level inferred from tab order; Business Arabic names came from page metadata). Pages for Sharia & Law, IT, Islamic Arts & Architecture, Hanafi and Maliki programmes could not be fetched (URL too long / empty), so those majors are taken from official study-plan file titles and department URLs: ''الفقه وأصوله'' (2024 plan), ''القانون'' (2025 plan; department is ''قسم القانون المقارن''), ''الفنون الإسلامية'' (2024 plan ''البكالوريوس فنون اسلامية''), IT: ''علم الحاسوب'' (department page), ''هندسة البرمجيات'' and ''نظم شبكات الحاسوب'' (2024 plans), ''نظم المعلومات والشبكات'' (department URL, 2020 plan). Maliki bachelor name ''الفقه المالكي وأصوله'' is inferred from the doctoral programme name and a 2020 bachelor plan titled ''خطة بكالوريوس المالكي''; Hanafi ''الفقه الحنفي'' from a 2021 plan title — exact official bachelor names unverified. Not included (unverified/possibly closed): ''أمن وسرية المعلومات والشبكات'' (2020 plan only), a bachelor in Islamic architecture / interior design (department ''قسم العمارة الإسلامية والتصميم الداخلي'' exists; bachelor name unknown), English-taught Hanafi & Shafi''i BA (online programmes page). The Technical College may offer more diplomas than the 3 IT ones; Maliki college also lists an intermediate-diploma level with no named programme. Email: domain wise.edu.jo assumed for staff/students; a Teams login guide exists but the student address format could not be read. Campus is at Tabarbour, Amman; coordinates not verified so lat/lng are null. Wikipedia gives colours green and maroon; no hex verified. Additional e-learning subdomains seen: learn.wise.edu.jo, elearning.wise.edu.jo (older semesters).')
on conflict (slug) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, city = excluded.city, email_domains = excluded.email_domains,
  center_lat = coalesce(excluded.center_lat, universities.center_lat), center_lng = coalesce(excluded.center_lng, universities.center_lng), data_notes = excluded.data_notes;
delete from university_links where university_id = (select id from universities where slug = 'wise');
select (select id from universities where slug = 'wise'), 'university', 'جامعة العلوم الإسلامية العالمية', 'مجتمع كل طلاب الجامعة' where not exists (select 1 from communities where university_id = (select id from universities where slug = 'wise') and kind = 'university');
values ('yu', 'جامعة اليرموك', 'Yarmouk University', 'إربد', 'public', array['yu.edu.jo','ses.yu.edu.jo']::text[], 32.53593, 35.85944, 'draft', 'The programme list (79 bachelor programmes) and the Arabic names come from YU Admission & Registration''s official ''التخصصات المتاحة لدرجة البكالوريوس 2026/2027'' (admreg.yu.edu.jo/images/docs/majors.pdf). In the extracted PDF text, programmes are not explicitly tied to faculty cells. The faculty grouping was inferred from list order and subject, and most programmes are unambiguous. UNCERTAIN: ''علم النفس الاكلينيكي'' (Clinical Psychology) appears between Pharmacy and Nursing. It is placed under the Faculty of Medicine here, but its faculty was not confirmed. The placements of ''التربية الفنية'' and ''الفنون الرقمية'' (Fine Arts), ''الواقع الرقمي وتطوير الألعاب'' (IT) and ''اللغة الفرنسية التطبيقية'' (Arts) are also inferred from position. The names ''دكتور في الطب'' and ''هندسة العمارة'' are marked ''(قبول سنوي)'' (annual intake) in the source. Fine Arts admission requires an aptitude exam, and Physical Education requires a medical exam. English programme names are translations: no current official English programme list was found, since majorsEn.pdf is an older 2021/2022 Arabic list. English faculty names come from yu.edu.jo/index.php/en/faculties. Faculty Arabic names follow the YU homepage, which writes ''كلية الاعمال'', ''كلية الاعلام'' and ''كلية الشريعة والدراسات الاسلامية'' without hamza. The homepage writes the IT faculty without ''كلية'' and with ''علوم الحاسوب''; the 2026/27 list writes ''علم الحاسوب''. Left out: the Technical College (الكلية التقنية), which appears on the homepage but has no programmes in the bachelor list, and no diploma programmes were found listed; also graduate studies. Email: students use @ses.yu.edu.jo (official YU page on the student email account) and staff use @yu.edu.jo. YU moved student and staff email from Gmail to Microsoft 365 on 29-12-2022 (official announcement), and the homepage email link is outlook.com/yu.edu.jo. The older ses.yu.edu.jo help page still mentions Gmail login, which is outdated. Microsoft Teams: no official link was found, so none is included. Center: map-centre coordinates from the ''University Map'' link on yu.edu.jo/index.php/en/yu-maps (32.535930, 35.859444). Wikipedia gives 32.5375, 35.85556. brand_color is null: Wikipedia lists the colours as green and white, but no official hex value was found. ''منصة اّبسول'' is linked on the homepage, but its purpose was not confirmed; it uses a Moodle-style /login/index.php path.')
on conflict (slug) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, city = excluded.city, email_domains = excluded.email_domains,
  center_lat = coalesce(excluded.center_lat, universities.center_lat), center_lng = coalesce(excluded.center_lng, universities.center_lng), data_notes = excluded.data_notes;
delete from university_links where university_id = (select id from universities where slug = 'yu');
select (select id from universities where slug = 'yu'), 'university', 'جامعة اليرموك', 'مجتمع كل طلاب الجامعة' where not exists (select 1 from communities where university_id = (select id from universities where slug = 'yu') and kind = 'university');
select set_config('unimate.system','off',true);
